@@ -0,0 +1,33 @@
+// Picks the response language from the request's Accept-Language header.
+import { LANGUAGES } from "../i18n/messages.js";
+
+const QVALUE = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/;
+
+/** The supported language `header` (an Accept-Language value) prefers, or `fallback`. */
+export function pickLanguage(header, fallback) {
+  if (typeof header !== "string") return fallback;
+  const ranges = [];
+  for (const part of header.split(",")) {
+    const [tag, ...params] = part.split(";").map((s) => s.trim().toLowerCase());
+    if (!/^(?:\*|[a-z]{1,8}(?:-[a-z0-9]{1,8})*)$/.test(tag)) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const m = /^q\s*=\s*(.*)$/.exec(p);
+      if (!m) continue;
+      if (QVALUE.test(m[1])) q = Number(m[1]);
+      else valid = false;
+    }
+    if (valid) ranges.push({ lang: tag.split("-")[0], q });
+  }
+  // q=0 refuses a language, also for a later `*`.
+  const refused = new Set(ranges.filter((r) => r.q === 0).map((r) => r.lang));
+  const wanted = ranges.filter((r) => r.q > 0).sort((a, b) => b.q - a.q);
+  for (const { lang } of wanted) {
+    if (lang === "*") {
+      const any = [fallback, ...LANGUAGES].find((l) => !refused.has(l));
+      if (any) return any;
+    } else if (LANGUAGES.includes(lang) && !refused.has(lang)) return lang;
+  }
+  return fallback;
+}
